{"command": "python3 << 'EOF'
from rdkit import Chem

# Input SMILES
smiles = "Cc1nc2ccc(-c3ccc([C@H](C)N4CC[C@](CC(C)(C)O)(c5ccccc5)OC4=O)cc3)cc2[nH]1"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print("Molecule parsed successfully")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Find the lactam ring
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.AROMATIC or bond.GetBondType() == Chem.BondType.SINGLE:
            atom1 = bond.GetBeginAtom()
            atom2 = bond.GetEndAtom()
            if atom1.GetAtomicNum() == 7 and atom2.GetAtomicNum() == 8:
                print(f"N-O bond found: N at {atom1.GetIdx()}, O at {atom2.GetIdx()}")
            if atom1.GetAtomicNum() == 8 and atom2.GetAtomicNum() == 7:
                print(f"O-N bond found: O at {atom1.GetIdx()}, N at {atom2.GetIdx()}")
            if atom1.GetAtomicNum() == 6 and atom2.GetAtomicNum() == 7:
                print(f"C-N bond: C at {atom1.GetIdx()}, N at {atom2.GetIdx()}")
            if atom1.GetAtomicNum() == 7 and atom2.GetAtomicNum() == 6:
                print(f"N-C bond: N at {atom1.GetIdx()}, C at {atom2.GetIdx()}")
else:
    print("Failed to parse molecule")
EOF
"}

